87	
88		private readonly _clients = new Map<string, IConnectedClient>();
89		private readonly _replayBuffer: IActionEnvelope[] = [];
90	
91		private readonly _onDidChangeConnectionCount = this._register(new Emitter<number>());
92	
93		/** Fires with the current client count whenever a client connects or disconnects. */
94		readonly onDidChangeConnectionCount = this._onDidChangeConnectionCount.event;
95	
96		constructor(
97			private readonly _stateManager: SessionStateManager,
98			private readonly _server: IProtocolServer,
99			private readonly _sideEffectHandler: IProtocolSideEffectHandler,
100			@ILogService private readonly _logService: ILogService,
101		) {
102			super();
103	
104			this._register(this._server.onConnection(transport => {
105				this._handleNewConnection(transport);
106			}));
107	
108			this._register(this._stateManager.onDidEmitEnvelope(envelope => {
109				this._replayBuffer.push(envelope);
110				if (this._replayBuffer.length > REPLAY_BUFFER_CAPACITY) {
111					this._replayBuffer.shift();
112				}
113				this._broadcastAction(envelope);
114			}));
115	
116			this._register(this._stateManager.onDidEmitNotification(notification => {
117				this._broadcastNotification(notification);
118			}));
119		}
120	
121		// ---- Connection handling -------------------------------------------------
122	
123		private _handleNewConnection(transport: IProtocolTransport): void {
124			const disposables = new DisposableStore();
125			let client: IConnectedClient | undefined;
